## 🎨 Client Setup (React Query Integration)

### Installing Dependencies

```bash
npm install @trpc/client @trpc/server @trpc/react-query @tanstack/react-query
```

### Next.js App Router Client Setup

```typescript
// app/providers.tsx
'use client';

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { httpBatchLink } from '@trpc/client';
import { createTRPCReact } from '@trpc/react-query';
import { useState } from 'react';
import { type AppRouter } from '@/server/routers/_app';

export const trpc = createTRPCReact<AppRouter>();

export function TRPCProvider({ children }: { children: React.ReactNode }) {
  const [queryClient] = useState(() => new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 5 * 1000,
        refetchOnWindowFocus: false,
      },
    },
  }));

  const [trpcClient] = useState(() =>
    trpc.createClient({
      links: [
        httpBatchLink({
          url: `${process.env.NEXT_PUBLIC_APP_URL}/api/trpc`,
          headers() {
            return {
              'x-trpc-source': 'client',
            };
          },
        }),
      ],
    })
  );

  return (
    <trpc.Provider client={trpcClient} queryClient={queryClient}>
      <QueryClientProvider client={queryClient}>
        {children}
      </QueryClientProvider>
    </trpc.Provider>
  );
}
```

```typescript
// app/layout.tsx
import { TRPCProvider } from './providers';

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>
        <TRPCProvider>{children}</TRPCProvider>
      </body>
    </html>
  );
}
```

### Using Queries

```typescript
'use client';

import { trpc } from '@/app/providers';

export function UserProfile() {
  // Simple query
  const { data, isLoading, error } = trpc.user.getCurrentUser.useQuery();

  // Query with input
  const { data: user } = trpc.user.getById.useQuery('user-id-123');

  // Query with complex input
  const { data: posts } = trpc.post.list.useQuery({
    userId: 'user-id',
    published: true,
  });

  if (isLoading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  return <div>Hello {data?.name}!</div>;
}
```

### Using Mutations

```typescript
'use client';

import { trpc } from '@/app/providers';

export function CreateUserForm() {
  const utils = trpc.useUtils();

  const createUser = trpc.user.create.useMutation({
    onSuccess(data) {
      // Invalidate and refetch
      utils.user.list.invalidate();

      // Or update cache directly
      utils.user.getById.setData(data.id, data);
    },
    onError(error) {
      console.error('Failed to create user:', error);
    },
  });

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    createUser.mutate({
      email: formData.get('email') as string,
      name: formData.get('name') as string,
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name="email" type="email" required />
      <input name="name" type="text" required />
      <button type="submit" disabled={createUser.isPending}>
        {createUser.isPending ? 'Creating...' : 'Create User'}
      </button>
      {createUser.error && <p>Error: {createUser.error.message}</p>}
    </form>
  );
}
```

### Optimistic Updates

Update UI immediately before server responds:

```typescript
export function TodoList() {
  const utils = trpc.useUtils();

  const toggleTodo = trpc.todo.toggle.useMutation({
    onMutate: async (id) => {
      // Cancel outgoing fetches
      await utils.todo.list.cancel();

      // Snapshot previous value
      const prevData = utils.todo.list.getData();

      // Optimistically update
      utils.todo.list.setData(undefined, (old) =>
        old?.map((todo) =>
          todo.id === id ? { ...todo, completed: !todo.completed } : todo
        )
      );

      return { prevData };
    },
    onError: (err, id, context) => {
      // Rollback on error
      utils.todo.list.setData(undefined, context?.prevData);
    },
    onSettled: () => {
      // Refetch after error or success
      utils.todo.list.invalidate();
    },
  });

  const { data: todos } = trpc.todo.list.useQuery();

  return (
    <ul>
      {todos?.map((todo) => (
        <li key={todo.id}>
          <input
            type="checkbox"
            checked={todo.completed}
            onChange={() => toggleTodo.mutate(todo.id)}
          />
          {todo.title}
        </li>
      ))}
    </ul>
  );
}
```

### Infinite Queries

Load data with pagination:

```typescript
export function InfinitePostList() {
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = trpc.post.listInfinite.useInfiniteQuery(
    { limit: 10 },
    {
      getNextPageParam: (lastPage) => lastPage.nextCursor,
    }
  );

  return (
    <div>
      {data?.pages.map((page) =>
        page.items.map((post) => (
          <article key={post.id}>
            <h2>{post.title}</h2>
            <p>{post.content}</p>
          </article>
        ))
      )}

      {hasNextPage && (
        <button onClick={() => fetchNextPage()} disabled={isFetchingNextPage}>
          {isFetchingNextPage ? 'Loading more...' : 'Load More'}
        </button>
      )}
    </div>
  );
}
```

✅ **Good**: Proper client setup
```typescript
// ✅ Batching requests
links: [
  httpBatchLink({
    url: '/api/trpc',
  }),
],
```

❌ **Bad**: No batching
```typescript
// ❌ Each request is separate (slower)
links: [
  httpLink({
    url: '/api/trpc',
  }),
],
```

---

## ⚠️ Error Handling

### TRPCError Types

tRPC provides standard error codes:

```typescript
import { TRPCError } from '@trpc/server';

// UNAUTHORIZED - User not authenticated
throw new TRPCError({
  code: 'UNAUTHORIZED',
  message: 'You must be logged in',
});

// FORBIDDEN - User not authorized
throw new TRPCError({
  code: 'FORBIDDEN',
  message: 'You do not have permission',
});

// NOT_FOUND - Resource not found
throw new TRPCError({
  code: 'NOT_FOUND',
  message: 'User not found',
});

// BAD_REQUEST - Invalid input
throw new TRPCError({
  code: 'BAD_REQUEST',
  message: 'Invalid email format',
});

// CONFLICT - Resource conflict
throw new TRPCError({
  code: 'CONFLICT',
  message: 'Email already exists',
});

// INTERNAL_SERVER_ERROR - Server error
throw new TRPCError({
  code: 'INTERNAL_SERVER_ERROR',
  message: 'Something went wrong',
});

// TOO_MANY_REQUESTS - Rate limit exceeded
throw new TRPCError({
  code: 'TOO_MANY_REQUESTS',
  message: 'Rate limit exceeded',
});

// TIMEOUT - Request timeout
throw new TRPCError({
  code: 'TIMEOUT',
  message: 'Request took too long',
});
```

### Custom Error Data

Add custom data to errors:

```typescript
export const userRouter = router({
  create: publicProcedure
    .input(z.object({
      email: z.string().email(),
      name: z.string(),
    }))
    .mutation(async ({ input }) => {
      const existing = await db.user.findUnique({
        where: { email: input.email },
      });

      if (existing) {
        throw new TRPCError({
          code: 'CONFLICT',
          message: 'User already exists',
          cause: {
            field: 'email',
            value: input.email,
          },
        });
      }

      return await db.user.create({ data: input });
    }),
});
```

### Error Formatting

Format errors for client consumption:

```typescript
// server/trpc.ts
import { initTRPC } from '@trpc/server';
import { ZodError } from 'zod';

const t = initTRPC.create({
  errorFormatter({ shape, error }) {
    return {
      ...shape,
      data: {
        ...shape.data,
        zodError:
          error.cause instanceof ZodError
            ? error.cause.flatten()
            : null,
        customField: 'custom data',
      },
    };
  },
});
```

### Client-Side Error Handling

Handle errors in React components:

```typescript
export function UserForm() {
  const createUser = trpc.user.create.useMutation({
    onError(error) {
      // Check error code
      if (error.data?.code === 'CONFLICT') {
        toast.error('Email already exists');
      } else if (error.data?.code === 'UNAUTHORIZED') {
        toast.error('Please log in');
      } else {
        toast.error('Something went wrong');
      }

      // Access Zod errors
      if (error.data?.zodError) {
        const fieldErrors = error.data.zodError.fieldErrors;
        console.log('Validation errors:', fieldErrors);
      }
    },
  });

  return (
    <form onSubmit={(e) => {
      e.preventDefault();
      createUser.mutate({ email: '...', name: '...' });
    }}>
      {/* Form fields */}
      {createUser.error && (
        <div className="error">
          {createUser.error.message}
        </div>
      )}
    </form>
  );
}
```

✅ **Good**: Specific error codes
```typescript
// ✅ Clear error codes
if (!user) {
  throw new TRPCError({
    code: 'NOT_FOUND',
    message: 'User not found',
  });
}
```

❌ **Bad**: Generic errors
```typescript
// ❌ Unclear error
if (!user) {
  throw new Error('Not found');
}
```

---

## 🔒 Type Safety (End-to-End)

### Automatic Type Inference

tRPC infers types automatically:

```typescript
// server/routers/user.ts
export const userRouter = router({
  getById: publicProcedure
    .input(z.string())
    .query(async ({ input }) => {
      return await db.user.findUnique({
        where: { id: input },
        select: {
          id: true,
          name: true,
          email: true,
          createdAt: true,
        },
      });
    }),
});
```

```typescript
// client/components/User.tsx
import { trpc } from '@/app/providers';

export function UserProfile({ userId }: { userId: string }) {
  const { data } = trpc.user.getById.useQuery(userId);

  // TypeScript knows exact shape:
  // data: { id: string; name: string; email: string; createdAt: Date } | undefined

  return <div>{data?.name}</div>; // ✅ Autocomplete works!
}
```

### AppRouter Type Export

Share types between server and client:

```typescript
// server/routers/_app.ts
import { router } from '../trpc';
import { userRouter } from './user';
import { postRouter } from './post';

export const appRouter = router({
  user: userRouter,
  post: postRouter,
});

// ⚠️ CRITICAL: Export only the TYPE, not the implementation
export type AppRouter = typeof appRouter;
```

```typescript
// app/providers.tsx
import { type AppRouter } from '@/server/routers/_app';
import { createTRPCReact } from '@trpc/react-query';

// Client gets full type safety
export const trpc = createTRPCReact<AppRouter>();
```

### Sharing Zod Schemas

Reuse validation schemas between server and client:

```typescript
// shared/schemas/user.ts
import { z } from 'zod';

export const createUserSchema = z.object({
  email: z.string().email('Invalid email'),
  name: z.string().min(1, 'Name required'),
  password: z.string().min(8, 'Password must be 8+ characters'),
});

export type CreateUserInput = z.infer<typeof createUserSchema>;
```

```typescript
// server/routers/user.ts
import { createUserSchema } from '@/shared/schemas/user';

export const userRouter = router({
  create: publicProcedure
    .input(createUserSchema)
    .mutation(async ({ input }) => {
      // input is typed as CreateUserInput
      return await db.user.create({ data: input });
    }),
});
```

```typescript
// app/components/UserForm.tsx
import { createUserSchema, type CreateUserInput } from '@/shared/schemas/user';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';

export function UserForm() {
  const form = useForm<CreateUserInput>({
    resolver: zodResolver(createUserSchema),
  });

  const createUser = trpc.user.create.useMutation();

  return (
    <form onSubmit={form.handleSubmit((data) => createUser.mutate(data))}>
      {/* Form fields with validation */}
    </form>
  );
}
```

### Type Inference Helpers

Extract types from procedures:

```typescript
import type { inferProcedureInput, inferProcedureOutput } from '@trpc/server';
import type { AppRouter } from '@/server/routers/_app';

// Infer input type
type CreateUserInput = inferProcedureInput<AppRouter['user']['create']>;

// Infer output type
type User = inferProcedureOutput<AppRouter['user']['getById']>;

// Use in your code
const user: User = {
  id: '1',
  name: 'John',
  email: 'john@example.com',
  createdAt: new Date(),
};
```

✅ **Good**: Full type safety
```typescript
// ✅ Types flow automatically
const { data } = trpc.user.getById.useQuery(userId);
data?.name; // TypeScript knows this exists
```

❌ **Bad**: Type assertions
```typescript
// ❌ Don't use 'any' or assertions
const { data } = trpc.user.getById.useQuery(userId) as any;
data.name; // No type safety!
```

