getUserData: publicProcedure.query(({ ctx }) => {
  if (!ctx.session) throw new TRPCError({ code: 'UNAUTHORIZED' });
  // ...
}),

updateUser: publicProcedure.mutation(({ ctx }) => {
  if (!ctx.session) throw new TRPCError({ code: 'UNAUTHORIZED' });
  // ...
}),
```

