### Using Mutations

```typescript
'use client';

import { trpc } from '@/app/providers';

export function CreateUserForm() {
  const utils = trpc.useUtils();

  const createUser = trpc.user.create.useMutation({
    onSuccess(data) {
      // Invalidate and refetch
      utils.user.list.invalidate();

      // Or update cache directly
      utils.user.getById.setData(data.id, data);
    },
    onError(error) {
      console.error('Failed to create user:', error);
    },
  });

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    createUser.mutate({
      email: formData.get('email') as string,
      name: formData.get('name') as string,
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name="email" type="email" required />
      <input name="name" type="text" required />
      <button type="submit" disabled={createUser.isPending}>
        {createUser.isPending ? 'Creating...' : 'Create User'}
      </button>
      {createUser.error && <p>Error: {createUser.error.message}</p>}
    </form>
  );
}
```

### Optimistic Updates

Update UI immediately before server responds:

```typescript
export function TodoList() {
  const utils = trpc.useUtils();

  const toggleTodo = trpc.todo.toggle.useMutation({
    onMutate: async (id) => {
      // Cancel outgoing fetches
      await utils.todo.list.cancel();

      // Snapshot previous value
      const prevData = utils.todo.list.getData();

      // Optimistically update
      utils.todo.list.setData(undefined, (old) =>
        old?.map((todo) =>
          todo.id === id ? { ...todo, completed: !todo.completed } : todo
        )
      );

      return { prevData };
    },
    onError: (err, id, context) => {
      // Rollback on error
      utils.todo.list.setData(undefined, context?.prevData);
    },
    onSettled: () => {
      // Refetch after error or success
      utils.todo.list.invalidate();
    },
  });

  const { data: todos } = trpc.todo.list.useQuery();

  return (
    <ul>
      {todos?.map((todo) => (
        <li key={todo.id}>
          <input
            type="checkbox"
            checked={todo.completed}
            onChange={() => toggleTodo.mutate(todo.id)}
          />
          {todo.title}
        </li>
      ))}
    </ul>
  );
}
```

