## 🔧 Procedures (Queries & Mutations)

### Query Procedures

Queries are for fetching data without side effects:

```typescript
import { publicProcedure, router } from '../trpc';
import { z } from 'zod';

export const blogRouter = router({
  // Simple query (no input)
  listAll: publicProcedure.query(async () => {
    return await db.post.findMany();
  }),

  // Query with input validation
  getById: publicProcedure
    .input(z.string().uuid())
    .query(async ({ input }) => {
      const post = await db.post.findUnique({
        where: { id: input },
      });

      if (!post) {
        throw new TRPCError({
          code: 'NOT_FOUND',
          message: 'Post not found',
        });
      }

      return post;
    }),

  // Query with complex input
  search: publicProcedure
    .input(z.object({
      query: z.string().min(1),
      tags: z.array(z.string()).optional(),
      authorId: z.string().optional(),
      limit: z.number().min(1).max(100).default(10),
      offset: z.number().min(0).default(0),
    }))
    .query(async ({ input }) => {
      return await db.post.findMany({
        where: {
          OR: [
            { title: { contains: input.query, mode: 'insensitive' } },
            { content: { contains: input.query, mode: 'insensitive' } },
          ],
          tags: input.tags ? { hasSome: input.tags } : undefined,
          authorId: input.authorId,
        },
        take: input.limit,
        skip: input.offset,
      });
    }),

  // Infinite query pattern
  listInfinite: publicProcedure
    .input(z.object({
      limit: z.number().min(1).max(100).default(10),
      cursor: z.string().optional(),
    }))
    .query(async ({ input }) => {
      const items = await db.post.findMany({
        take: input.limit + 1,
        cursor: input.cursor ? { id: input.cursor } : undefined,
        orderBy: { createdAt: 'desc' },
      });

      let nextCursor: string | undefined;
      if (items.length > input.limit) {
        const nextItem = items.pop();
        nextCursor = nextItem!.id;
      }

      return {
        items,
        nextCursor,
      };
    }),
});
```

✅ **Good**: Proper query design
```typescript
// ✅ Query has no side effects
getUser: publicProcedure
  .input(z.string())
  .query(async ({ input }) => {
    return await db.user.findUnique({ where: { id: input } });
  }),
```

❌ **Bad**: Query with side effects
```typescript
// ❌ Don't modify data in queries!
getUser: publicProcedure
  .input(z.string())
  .query(async ({ input }) => {
    // ❌ Incrementing view count in a query
    await db.user.update({
      where: { id: input },
      data: { views: { increment: 1 } },
    });
    return await db.user.findUnique({ where: { id: input } });
  }),
```

### Mutation Procedures

Mutations are for creating, updating, or deleting data:

```typescript
export const userRouter = router({
  // Create mutation
  create: publicProcedure
    .input(z.object({
      email: z.string().email(),
      name: z.string().min(1),
      password: z.string().min(8),
    }))
    .mutation(async ({ input }) => {
      const hashedPassword = await hash(input.password);

      const user = await db.user.create({
        data: {
          email: input.email,
          name: input.name,
          password: hashedPassword,
        },
      });

      return {
        id: user.id,
        email: user.email,
        name: user.name,
      };
    }),

  // Update mutation
  update: publicProcedure
    .input(z.object({
      id: z.string(),
      name: z.string().min(1).optional(),
      bio: z.string().optional(),
    }))
    .mutation(async ({ input, ctx }) => {
      if (!ctx.session?.user) {
        throw new TRPCError({ code: 'UNAUTHORIZED' });
      }

      const { id, ...data } = input;

      return await db.user.update({
        where: { id },
        data,
      });
    }),

  // Delete mutation
  delete: publicProcedure
    .input(z.string())
    .mutation(async ({ input, ctx }) => {
      if (!ctx.session?.user) {
        throw new TRPCError({ code: 'UNAUTHORIZED' });
      }

      await db.user.delete({ where: { id: input } });

      return { success: true };
    }),

  // Complex mutation with transaction
  transferOwnership: publicProcedure
    .input(z.object({
      postId: z.string(),
      newOwnerId: z.string(),
    }))
    .mutation(async ({ input, ctx }) => {
      return await db.$transaction(async (tx) => {
        // Update post ownership
        const post = await tx.post.update({
          where: { id: input.postId },
          data: { authorId: input.newOwnerId },
        });

        // Create activity log
        await tx.activity.create({
          data: {
            type: 'OWNERSHIP_TRANSFER',
            postId: input.postId,
            fromUserId: ctx.session!.user.id,
            toUserId: input.newOwnerId,
          },
        });

        return post;
      });
    }),
});
```

### Input Validation with Zod

tRPC uses Zod for runtime validation:

```typescript
import { z } from 'zod';

export const formRouter = router({
  // Basic types
  submitBasic: publicProcedure
    .input(z.object({
      string: z.string(),
      number: z.number(),
      boolean: z.boolean(),
      date: z.date(),
    }))
    .mutation(({ input }) => input),

  // Advanced validation
  submitAdvanced: publicProcedure
    .input(z.object({
      email: z.string().email(),
      url: z.string().url(),
      uuid: z.string().uuid(),
      age: z.number().min(18).max(120),
      password: z.string().min(8).regex(/[A-Z]/).regex(/[0-9]/),
      enum: z.enum(['ADMIN', 'USER', 'GUEST']),
    }))
    .mutation(({ input }) => input),

  // Optional and nullable
  submitOptional: publicProcedure
    .input(z.object({
      required: z.string(),
      optional: z.string().optional(),
      nullable: z.string().nullable(),
      withDefault: z.string().default('default value'),
    }))
    .mutation(({ input }) => input),

  // Arrays and objects
  submitComplex: publicProcedure
    .input(z.object({
      tags: z.array(z.string()),
      metadata: z.record(z.string()),
      nested: z.object({
        deep: z.object({
          value: z.number(),
        }),
      }),
    }))
    .mutation(({ input }) => input),

  // Discriminated unions
  submitUnion: publicProcedure
    .input(z.discriminatedUnion('type', [
      z.object({
        type: z.literal('email'),
        email: z.string().email(),
      }),
      z.object({
        type: z.literal('phone'),
        phone: z.string().regex(/^\+?[1-9]\d{1,14}$/),
      }),
    ]))
    .mutation(({ input }) => {
      if (input.type === 'email') {
        // input.email is available
        return { method: 'email', value: input.email };
      } else {
        // input.phone is available
        return { method: 'phone', value: input.phone };
      }
    }),
});
```

✅ **Good**: Strong input validation
