## 🖥️ Server Setup (Express + Zod)

### Initialize Express

```typescript
// server/src/index.ts
import express from 'express';
import cors from 'cors';
import { userRouter } from './routers/user';
import { postRouter } from './routers/post';
import { authMiddleware } from './middleware/auth';

const app = express();
app.use(cors());
app.use(express.json());

// Auth middleware (applied globally or per route)
app.use('/api/*', authMiddleware); // except login/register

// Routers
app.use('/api/users', userRouter);
app.use('/api/posts', postRouter);

app.listen(4000, () => console.log('Server on :4000'));
```

### User Router (CRUD)

```typescript
// server/src/routers/user.ts
import { Router } from 'express';
import { createUserSchema, updateUserSchema } from '@myapp/shared';
import { prisma } from '../db';

export const userRouter = Router();

// Create
userRouter.post('/', async (req, res) => {
  const input = createUserSchema.parse(req.body);  // validates & throws
  const user = await prisma.user.create({ data: input });
  res.json(user);
});

// Read by ID
userRouter.get('/:id', async (req, res) => {
  const user = await prisma.user.findUnique({ where: { id: req.params.id } });
  if (!user) return res.status(404).json({ message: 'User not found' });
  res.json(user);
});

// List (cursor-based pagination)
userRouter.get('/', async (req, res) => {
  const { limit, cursor } = paginationSchema.parse(req.query);
  const users = await prisma.user.findMany({
    take: limit + 1,
    cursor: cursor ? { id: cursor } : undefined,
  });
  let nextCursor: string | undefined;
  if (users.length > limit) {
    const nextItem = users.pop();
    nextCursor = nextItem!.id;
  }
  res.json({ users, nextCursor });
});

// Update
userRouter.patch('/:id', async (req, res) => {
  const input = updateUserSchema.parse({ id: req.params.id, ...req.body });
  const user = await prisma.user.update({ where: { id: input.id }, data: input });
  res.json(user);
});

// Delete
userRouter.delete('/:id', async (req, res) => {
  await prisma.user.delete({ where: { id: req.params.id } });
  res.json({ success: true });
});
```

### Post Router

```typescript
// server/src/routers/post.ts
import { Router } from 'express';
import { createPostSchema, listPostsSchema } from '@myapp/shared';
import { prisma } from '../db';

export const postRouter = Router();

// Create
postRouter.post('/', async (req, res) => {
  const input = createPostSchema.parse(req.body);
  const post = await prisma.post.create({ data: input });
  res.json(post);
});

// Read by ID (include author)
postRouter.get('/:id', async (req, res) => {
  const post = await prisma.post.findUnique({
    where: { id: req.params.id },
    include: { author: true },
  });
  if (!post) return res.status(404).json({ message: 'Post not found' });
  res.json(post);
});

// List with filters
postRouter.get('/', async (req, res) => {
  const filters = listPostsSchema.parse(req.query);
  const posts = await prisma.post.findMany({
    where: {
      authorId: filters.userId || undefined,
      published: filters.published !== undefined ? filters.published : undefined,
    },
    include: { author: true },
  });
  res.json(posts);
});
```

