### Type-safe Hooks (Manual Types)

You must manually define types that match your shared schemas. These are NOT automatically inferred from the server.

```typescript
// client/src/api/types.ts
// Manually copied from shared schemas (or import if shared package is available)
export interface User {
  id: string;
  email: string;
  name: string;
  createdAt: string; // Date serialized as string
}

export interface Post {
  id: string;
  title: string;
  content: string;
  authorId: string;
  author: User | null;
  published: boolean;
  createdAt: string;
}

export interface CreateUserInput {
  email: string;
  name: string;
}

export interface UpdateUserInput {
  id: string;
  email?: string;
  name?: string;
}

export interface CreatePostInput {
  title: string;
  content: string;
  authorId: string;
}

export interface PaginatedResponse<T> {
  users: T[];  // adjust based on endpoint
  nextCursor?: string;
}
```

**⚠️ Warning**: Every time you add a field in the server schema, you must update these types manually. There is no automatic synchronization.

### React Query Hooks for Users

```typescript
// client/src/hooks/useUsers.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../api/client';
import type { User, CreateUserInput, UpdateUserInput, PaginatedResponse } from '../api/types';

export function useUsersList(cursor?: string) {
  return useQuery<PaginatedResponse<User>>({
    queryKey: ['users', 'list', cursor],
    queryFn: () => api.get('/users', { params: { cursor } }).then(res => res.data),
  });
}

export function useUser(id: string) {
  return useQuery<User>({
    queryKey: ['users', id],
    queryFn: () => api.get(`/users/${id}`).then(res => res.data),
    enabled: !!id,
  });
}

export function useCreateUser() {
  const queryClient = useQueryClient();
  return useMutation<User, Error, CreateUserInput>({
    mutationFn: (data) => api.post('/users', data).then(res => res.data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
    },
  });
}

export function useUpdateUser() {
  const queryClient = useQueryClient();
  return useMutation<User, Error, UpdateUserInput>({
    mutationFn: ({ id, ...data }) => api.patch(`/users/${id}`, data).then(res => res.data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
    },
  });
}

export function useDeleteUser() {
  const queryClient = useQueryClient();
  return useMutation<{ success: boolean }, Error, string>({
    mutationFn: (id) => api.delete(`/users/${id}`).then(res => res.data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['users'] });
    },
  });
}
```

### React Query Hooks for Posts

```typescript
// client/src/hooks/usePosts.ts
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../api/client';
import type { Post, CreatePostInput } from '../api/types';

export function usePost(id: string) {
  return useQuery<Post>({
    queryKey: ['posts', id],
    queryFn: () => api.get(`/posts/${id}`).then(res => res.data),
    enabled: !!id,
  });
}

export function usePostsList(filters?: { userId?: string; published?: boolean }) {
  return useQuery<Post[]>({
    queryKey: ['posts', 'list', filters],
    queryFn: () => api.get('/posts', { params: filters }).then(res => res.data),
  });
}

export function useCreatePost() {
  const queryClient = useQueryClient();
  return useMutation<Post, Error, CreatePostInput>({
    mutationFn: (data) => api.post('/posts', data).then(res => res.data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['posts'] });
    },
  });
}
```

### Optimistic Updates Example

```typescript
export function useCreatePostWithOptimistic() {
  const queryClient = useQueryClient();
  return useMutation<Post, Error, CreatePostInput>({
    mutationFn: (data) => api.post('/posts', data).then(res => res.data),
    onMutate: async (newPost) => {
      await queryClient.cancelQueries({ queryKey: ['posts'] });
      const previousPosts = queryClient.getQueryData<Post[]>(['posts', 'list']);
      // Optimistically add a temporary post
      const optimisticPost: Post = { id: 'temp', ...newPost, author: null, published: false, createdAt: new Date().toISOString() };
      queryClient.setQueryData(['posts', 'list'], (old: Post[] | undefined) => [...(old || []), optimisticPost]);
      return { previousPosts };
    },
    onError: (err, newPost, context) => {
      queryClient.setQueryData(['posts', 'list'], context?.previousPosts);
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ['posts'] });
    },
  });
}
```

### Usage in Components

```typescript
// client/src/components/UserForm.tsx
import { useCreateUser } from '../hooks/useUsers';

export function UserForm() {
  const createUser = useCreateUser();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const form = new FormData(e.currentTarget as HTMLFormElement);
    createUser.mutate({ email: form.get('email') as string, name: form.get('name') as string });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input name="email" type="email" required />
      <input name="name" required />
      <button type="submit" disabled={createUser.isPending}>
        {createUser.isPending ? 'Creating...' : 'Create User'}
      </button>
    </form>
  );
}
```

